import{_ as l,C as r,o as i,c as h,j as d,a as c,E as e,al as a}from"./chunks/framework.D1FqHTxE.js";const q=JSON.parse('{"title":"FunnelChart 漏斗图","description":"","frontmatter":{},"headers":[],"relativePath":"components/funnel-chart.md","filePath":"components/funnel-chart.md","lastUpdated":1790578088000}'),s={name:"components/funnel-chart.md"},p={id:"funnelchart-漏斗图",tabindex:"-1"};function u(b,t,m,g,f,x){const n=r("Badge"),o=r("XhDemo");return i(),h("div",null,[d("h1",p,[t[0]||(t[0]=c("FunnelChart 漏斗图 ",-1)),e(n,{type:"tip",text:"new"}),t[1]||(t[1]=c()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#funnelchart-漏斗图","aria-label":'Permalink to "FunnelChart 漏斗图 <Badge type="tip" text="new" />"'},"​",-1))]),t[3]||(t[3]=a('<p>看一个流程里各阶段的保留量与逐级转化率。每个阶段一行，宽度与数值成正比，相邻阶段之间写出转化率。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/funnel-chart" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/funnel-chart.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/funnel-chart" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/funnel-chart" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/funnel-chart.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一行数据一个阶段、按先后排好：宽度与数值成正比，相邻阶段之间写出相对上一阶段的转化率</p>',4)),e(o,{src:"funnel-chart/01-basic"}),t[4]||(t[4]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;funnel-chart&quot;</code>：<strong><code>root</code></strong> · <code>caption</code> · <strong><code>viewport</code></strong> · <strong><code>plot</code></strong> · <code>stage</code> · <code>stage-label</code> · <code>conversion</code> · <code>focus-ring</code> · <code>tooltip</code> · <code>tooltip-header</code> · <code>tooltip-row</code> · <code>tooltip-swatch</code> · <code>tooltip-value</code> · <code>tooltip-name</code> · <code>empty</code> · <code>summary</code> · <code>table</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="条形" tabindex="-1">条形 <a class="header-anchor" href="#条形" aria-label="Permalink to &quot;条形&quot;">​</a></h3><p>shape=&quot;bar&quot; 画成等高的条形：阶段之间要仔细比较宽度时比梯形的斜边好对齐</p>',6)),e(o,{src:"funnel-chart/02-bar"}),t[5]||(t[5]=d("h3",{id:"相对第一阶段",tabindex:"-1"},[c("相对第一阶段 "),d("a",{class:"header-anchor",href:"#相对第一阶段","aria-label":'Permalink to "相对第一阶段"'},"​")],-1)),t[6]||(t[6]=d("p",null,'conversion="first" 让每个阶段写相对第一阶段的转化率：读者关心从头到尾留下多少',-1)),e(o,{src:"funnel-chart/03-first"}),t[7]||(t[7]=d("h3",{id:"靠左对齐",tabindex:"-1"},[c("靠左对齐 "),d("a",{class:"header-anchor",href:"#靠左对齐","aria-label":'Permalink to "靠左对齐"'},"​")],-1)),t[8]||(t[8]=d("p",null,'align="start" 让阶段靠起始边对齐，逐级缩短看得更清楚',-1)),e(o,{src:"funnel-chart/04-start"}),t[9]||(t[9]=d("h3",{id:"金字塔",tabindex:"-1"},[c("金字塔 "),d("a",{class:"header-anchor",href:"#金字塔","aria-label":'Permalink to "金字塔"'},"​")],-1)),t[10]||(t[10]=d("p",null,'direction="up" 画成金字塔：第一阶段在最下面，往上逐级收窄；层级之间是包含关系，不写转化率',-1)),e(o,{src:"funnel-chart/05-pyramid"}),t[11]||(t[11]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>流程有固定的先后，每一步都从上一步里留下一部分：访问 → 注册 → 下单、线索 → 商机 → 成交。</li><li>读者要找的是「在哪一步流失最多」，以及从头到尾留下多少。</li><li>金字塔（<code>direction=&quot;up&quot;</code>）用于层级之间有包含关系、越往上越少的构成：人口年龄段、组织层级。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>阶段之间没有先后，只是几个并列的类目：用<a href="./cartesian-chart">直角坐标图</a>的横向条形图。</li><li>要看各部分占整体的比例：用<a href="./pie-chart">饼图</a>。</li><li>要看转化随时间的变化：一串漏斗读不出趋势，把每一步的转化率画成折线。</li><li>只有两个阶段：一个百分比就说清了，用<a href="./statistic">统计数值</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>数据是对象数组，按阶段的先后排好，每行一个阶段：<code>nameField</code> 指定阶段名所在的字段，<code>valueField</code> 指定数值所在的字段。数值为负时报 <code>chart.negative-share</code>，字段不存在时报 <code>chart.unknown-field</code>，根上写 <code>data-state=&quot;error&quot;</code>；阶段值不要求递减，递增时转化率写成大于 100%。</li><li>阶段的宽度与数值成正比，最宽的阶段铺满漏斗占的宽度。<code>shape</code> 取 <code>trapezoid</code>（缺省）时上下两条边分别接着自己与下一阶段的宽度，最后一个阶段两条边一样宽；<code>bar</code> 画成等高的条形，各阶段之间更好比较。<code>align</code> 取 <code>center</code>（缺省）居中，<code>start</code> 靠起始边对齐，逐级缩短看得更清楚。</li><li><code>direction=&quot;up&quot;</code> 画成金字塔：第一阶段在最下面，往上逐级收窄。</li><li>颜色取有序色阶：第一阶段最深，往后逐级变浅，到色阶的 30% 为止（更浅的一段压在承载面上看不清）。阶段有固有次序，不用分类色，也就没有图例，阶段名直接标在阶段上。<code>palette</code> 把色阶换到基础色板里同名的色相上，与热力图、按值着色的散点同名。</li><li>阶段标签写阶段名与数值：<code>labels=&quot;outside&quot;</code>（缺省）跟在各阶段的右边，漏斗让出最长那条标签的宽度，字压在承载面上，深浅两端都读得清；<code>inside</code> 写在阶段里、描一圈承载面色，放不下时写到阶段右边。</li><li><code>conversion</code> 取 <code>previous</code>（缺省，相对上一阶段）或 <code>first</code>（相对第一阶段）时，转化率写在左侧一列、落在两个阶段的交界处；<code>none</code> 不写，左侧不留列。</li><li>指着一行就命中那个阶段，窄的阶段两侧的空白也算；提示框写数值与两种转化率（第一阶段只有数值），其余阶段与它们的标签淡出到 <code>--xh-chart-dim-alpha</code>，被指着的阶段不位移、不放大。</li><li><code>hiddenSeries</code> 隐藏的阶段不画，转化率跳过它按相邻的可见阶段重算。</li><li><code>format</code> 指定数值格式（数字格式或函数），标签、提示框、可及名与数据表共用；转化率固定写成一位小数的百分数。</li><li>多张图接到同一个受控的 <code>activeKey</code> 上时，漏斗图按阶段名与其他图的类目对齐。</li><li><code>pending</code> 表示正在重新取数：保留上一帧、整体降低不透明度并在根上写 <code>aria-busy</code>。首次取数、手里还没有阶段时，空态写 <code>translations.loadingText</code> 并转一个圈，取完仍没有数据才写 <code>emptyText</code>。</li><li>首次出现时各阶段从中线（<code>align=&quot;start&quot;</code> 时从起始边）一起横向展开，标签与转化率淡入，数据晚于挂载到达（异步取数，或 Web Components 连上之后才赋 <code>data</code>）时同样播这段入场；之后的数据变化从当前宽度插值到新宽度。<code>animated={false}</code>（Web Components 写 <code>animated=&quot;false&quot;</code>）关闭过渡；系统开了减弱动效或容器写了 <code>data-motion=&quot;reduce&quot;</code> 时几何直接到位，只保留淡入淡出。</li><li>三个适配器的作者侧写法不同，最终 DOM 一致：Vue 与 React 不写默认内容时铺开缺省结构（标题、视口与绘图区、空态、提示框），提示框内容可由作用域插槽 / 函数式 children 替换；Web Components 侧作者写外壳（root、caption、viewport 与其中空的 <code>&lt;svg&gt;</code> plot，可选 empty 与 tooltip），阶段、标签与转化率由元素生成进去。</li><li>Web Components 侧的数据与数值格式只走 JS property；字段名、形状、对齐、方向、转化率、标签、色板与 <code>active-key</code> 另有同名属性。宿主元素缺省是行内元素，放进 flex / grid 时要给它一个宽度。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>为图写标题：<code>caption</code> 是图的可访问名称，也要说明流程是什么、统计的是哪段时间。</li><li>阶段保持在 3–7 个；更长的流程拆成几段，或把相近的步骤并起来。</li><li>读者关心逐步流失时用 <code>previous</code>，关心从头到尾留下多少时用 <code>first</code>；两种都要时读提示框与数据表。</li><li>各阶段之间要仔细比较数值时改用 <code>shape=&quot;bar&quot;</code>，梯形的斜边会让宽度难以对齐。</li><li>需要可见的表格视图时，把 <code>api.table</code> 交给<a href="./table">表格</a>组件（Vue 与 React 从根的作用域插槽 / 函数式 children 取 <code>table</code>，Web Components 读元素的 <code>table</code>）。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用漏斗画没有先后的类目：读者会把宽度的递减读成流失。</li><li>把不同时间段、不同口径的数放进同一个漏斗：转化率失去含义。</li><li>为了好看让阶段宽度不按数值：漏斗的形状本身就是数据。</li><li>把提示框当作读取转化率的唯一途径：提示框对读屏隐藏，数值要能从标签、摘要或数据表读到。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-funnel-chart&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhFunnelChartCaption</code> <code>XhFunnelChartEmpty</code> <code>XhFunnelChartPlot</code> <code>XhFunnelChartRoot</code> <code>XhFunnelChartTooltip</code> <code>XhFunnelChartViewport</code></td></tr><tr><td>组合式函数</td><td><code>useFunnelChart</code></td></tr><tr><td>状态机</td><td><code>funnelChartMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/funnel-chart.css</code></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hidden-series-change</code></td><td><code>ChartHiddenSeriesChangeDetails</code></td><td>阶段的显隐变了；detail 为 <code>{ hiddenSeries: string[] }</code></td></tr><tr><td><code>active-key-change</code></td><td><code>ChartActiveKeyChangeDetails</code></td><td>指针或键盘换了激活的阶段；detail 为 <code>{ activeKey }</code>，收起时为 null</td></tr><tr><td><code>datum-active</code></td><td><code>ChartDatumDetails</code></td><td>悬停或聚焦到某个阶段；detail 为阶段详情，收起时为 null</td></tr><tr><td><code>datum-press</code></td><td><code>ChartDatumDetails</code></td><td>指针点击、Enter 或 Space 按在某个阶段上；detail 为阶段详情</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhFunnelChartRoot</code></td><td><code>default</code></td><td><code>FunnelChartRootSlotProps</code></td><td>自行摆放部件；不写时铺开缺省结构：视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>caption</code></td><td>—</td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>tooltip</code></td><td><code>FunnelChartTooltipSlotProps</code></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>empty</code></td><td>—</td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhFunnelChartTooltip</code></td><td><code>default</code></td><td><code>FunnelChartTooltipSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhFunnelChartRoot</code></td><td><code>data</code></td><td><code>readonly ChartRow[]</code></td><td></td><td>数据：对象数组，按阶段的先后排好，每行一个阶段。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>nameField</code></td><td><code>string</code></td><td></td><td>阶段名所在的字段。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>valueField</code></td><td><code>string</code></td><td></td><td>数值所在的字段。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>shape</code></td><td><code>FunnelShape</code></td><td></td><td>阶段的形状，缺省 trapezoid。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>align</code></td><td><code>FunnelAlign</code></td><td></td><td>阶段的对齐，缺省 center。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>direction</code></td><td><code>FunnelDirection</code></td><td></td><td>排列方向，缺省 down；up 即金字塔。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>conversion</code></td><td><code>FunnelConversion</code></td><td></td><td>转化率的基准，缺省 previous。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>labels</code></td><td><code>FunnelLabels</code></td><td></td><td>阶段标签，缺省 inside。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>palette</code></td><td><code>ChartPalette</code></td><td></td><td>顺序色阶的色板。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>format</code></td><td><code>NumberFormatSpec | ((value: number) =&gt; string)</code></td><td></td><td>数值格式。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td><td>隐藏的阶段（受控）。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>defaultHiddenSeries</code></td><td><code>string[]</code></td><td></td><td>初始隐藏的阶段（非受控）。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td><td>激活的键（受控）：与别的图联动时是阶段名。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>pending</code></td><td><code>boolean</code></td><td></td><td>数据重取中：保留上一帧、整体降低不透明度。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>animated</code></td><td><code>boolean</code></td><td></td><td>播放过渡动画，缺省 true；false 时直接画终态。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>locale</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>translations</code></td><td><code>Partial&lt;FunnelChartTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>onHiddenSeriesChange</code></td><td><code>FunnelChartProps[&#39;onHiddenSeriesChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>onActiveKeyChange</code></td><td><code>FunnelChartProps[&#39;onActiveKeyChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>onDatumActive</code></td><td><code>FunnelChartProps[&#39;onDatumActive&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>onDatumPress</code></td><td><code>FunnelChartProps[&#39;onDatumPress&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>caption</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>renderTooltip</code></td><td><code>(props: FunnelChartTooltipSlotProps) =&gt; ReactNode</code></td><td></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>empty</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhFunnelChartRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;FunnelChartRootSlotProps&gt;</code></td><td></td><td>自行摆放部件；不写时铺开缺省结构：视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhFunnelChartTooltip</code></td><td><code>children</code></td><td><code>SlotChildren&lt;FunnelChartTooltipSlotProps&gt;</code></td><td></td><td>替换缺省内容；函数式 children 拿到激活的阶段与缺省的内容模型。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>empty</code></td><td>&#39;loading&#39; | undefined</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>FunnelModel</code></td><td>管线产物：阶段、布局、场景与无障碍模型。</td></tr><tr><td><code>scene</code></td><td><code>Scene</code></td><td>要画的场景；尚未测量时为空场景。</td></tr><tr><td><code>overlay</code></td><td><code>FunnelOverlay</code></td><td>前景层：焦点环画在阶段之上。</td></tr><tr><td><code>measured</code></td><td><code>boolean</code></td><td>视口尚未测量（服务端与首帧）。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>没有可画的阶段。</td></tr><tr><td><code>active</code></td><td><code>ChartDatumDetails | null</code></td><td>激活的阶段；没有时为 null。</td></tr><tr><td><code>tooltip</code></td><td><code>FunnelTooltipModel | null</code></td><td>提示框内容；收起时为 null。</td></tr><tr><td><code>summary</code></td><td><code>string</code></td><td></td></tr><tr><td><code>table</code></td><td><code>TableModel</code></td><td>数据表模型：阶段名、数值、相对上一阶段、相对第一阶段四列。</td></tr><tr><td><code>emptyText</code></td><td><code>string</code></td><td></td></tr><tr><td><code>tableCaption</code></td><td><code>string</code></td><td></td></tr><tr><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td></tr><tr><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>toggleSeries</code></td><td><code>(id: string) =&gt; void</code></td><td>切换某个阶段的显隐：隐藏的阶段不画，转化率跳过它重算。</td></tr><tr><td><code>setFocusedDatum</code></td><td><code>(ref: { seriesId: string, index: number } | null) =&gt; void</code></td><td>移动键盘锚点：只改锚点，不移动 DOM 焦点，也不派发回调。</td></tr><tr><td><code>markTag</code></td><td><code>(mark: Mark) =&gt; FunnelMarkTag</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCaptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPlotProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMarkProps</code></td><td><code>(mark: Mark) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipRowProps</code></td><td><code>(row: FunnelTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipSwatchProps</code></td><td><code>(row: FunnelTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipValueProps</code></td><td><code>(row: FunnelTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipNameProps</code></td><td><code>(row: FunnelTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getEmptyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTableProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>总是</td><td>绘图区只占一个 Tab 位：焦点落到锚点阶段，首次为第一阶段</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>焦点在绘图区</td><td>下一阶段；金字塔里由 ArrowUp 承担；已在最后一个则原地不动</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>焦点在绘图区</td><td>上一阶段；金字塔里由 ArrowDown 承担</td></tr><tr><td><code>Home</code></td><td>焦点在绘图区</td><td>第一阶段</td></tr><tr><td><code>End</code></td><td>焦点在绘图区</td><td>最后一个阶段</td></tr><tr><td><code>PageUp</code> / <code>PageDown</code></td><td>焦点在绘图区</td><td>跨 10% 的阶段，至少 1 个</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在绘图区</td><td>报告聚焦的阶段（onDatumPress）</td></tr><tr><td><code>Escape</code></td><td>提示框显示着</td><td>收起提示框，焦点留在原处；按键不拦截，外层浮层的关闭仍归它自己</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>plot</code></td><td><code>aria-describedby</code></td><td><code>summary</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-labelledby</code></td><td><code>caption</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-roledescription</code></td><td>translations.chartRoleDescription</td></tr><tr><td><code>plot</code></td><td><code>role</code></td><td>&#39;graphics-document&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>mark</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根是 <code>&lt;figure&gt;</code>，可访问名称来自 <code>caption</code>；不放标题时在根上写 <code>aria-label</code>。</li><li>绘图区是 <code>role=&quot;graphics-document&quot;</code>，<code>aria-describedby</code> 指向组件生成的摘要；每个阶段是 <code>role=&quot;graphics-symbol&quot;</code>，名称取 <code>translations.datumLabel</code>（缺省「阶段名, 数值, 相对上一阶段的转化率」），务必按本地语言改写。</li><li>绘图区只占一个 Tab 位，焦点落在阶段上：右键与下键到下一阶段，左键与上键到上一阶段；金字塔里上下两个键跟着画面对调。Home / End 到第一与最后一个阶段。焦点环画在阶段之外，只在键盘聚焦时出现。</li><li>阶段标签、转化率与焦点环一律 <code>aria-hidden</code>：它们的内容已在阶段的名称里；提示框同样 <code>aria-hidden</code>。</li><li>组件在根内生成一段摘要与一张数据表，视觉隐藏、对读屏可见：摘要写阶段数、首尾两个阶段、从头到尾的转化率与流失最多的一步（模板是 <code>translations.summary</code>）；数据表四列是阶段名、数值、相对上一阶段与相对第一阶段（列名取 <code>nameLabel</code>、<code>valueLabel</code>、<code>previousLabel</code>、<code>firstLabel</code>）。</li><li>颜色不承载身份：阶段名写在阶段上，次序由位置表达；强制色下阶段改成系统色的面与描边。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/funnel-chart.css</code> 使用 <code>[data-scope=&quot;funnel-chart&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-palette</code></td><td>props.palette</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>data-xh-chart-part</code></td><td>&#39;root&#39;</td></tr><tr><td><code>caption</code></td><td><code>data-xh-chart-part</code></td><td>&#39;caption&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-xh-chart-part</code></td><td>&#39;viewport&#39;</td></tr><tr><td><code>plot</code></td><td><code>data-xh-chart-part</code></td><td>&#39;plot&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-placement</code></td><td>&#39;top&#39; | &#39;bottom&#39;-&#39;right&#39; | &#39;left&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>tooltip-header</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-header&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-row&#39;</td></tr><tr><td><code>tooltip-swatch</code></td><td><code>data-seg</code></td><td>stop?.seg</td></tr><tr><td><code>tooltip-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-swatch&#39;</td></tr><tr><td><code>tooltip-value</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-value&#39;</td></tr><tr><td><code>tooltip-name</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-name&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>empty</code></td><td><code>data-state</code></td><td>&#39;loading&#39; | undefined</td></tr><tr><td><code>empty</code></td><td><code>data-xh-chart-part</code></td><td>&#39;empty&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-xh-loading-ring</code></td><td>&#39;&#39;</td></tr><tr><td><code>mark</code></td><td><code>data-dimmed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>mark</code></td><td><code>data-placement</code></td><td>&#39;inside&#39; | &#39;outside&#39; | undefined</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-part</code></td><td>mark.part | undefined</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-funnel-chart-empty-gap</code></td><td><code>empty</code></td><td><code>gap</code></td><td><code>state=loading</code></td><td><code>--xh-space-2</code></td><td>funnel-chart 的 empty 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>funnel-chart 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-height</code></td><td><code>viewport</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-chart-height</code></td><td>funnel-chart 的 viewport 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-stage-gap</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-gap</code></td><td><code>default</code></td><td><code>--xh-chart-gap</code></td><td>funnel-chart 的 root 部件 --xh-_chart-metric-gap 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-tooltip-gap</code></td><td><code>tooltip</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>funnel-chart 的 tooltip 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-tooltip-px</code></td><td><code>tooltip</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>funnel-chart 的 tooltip 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-tooltip-py</code></td><td><code>tooltip</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>funnel-chart 的 tooltip 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-tooltip-radius</code></td><td><code>tooltip</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-overlay</code></td><td>funnel-chart 的 tooltip 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-tooltip-row-gap</code></td><td><code>tooltip-row</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>funnel-chart 的 tooltip-row 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-tooltip-shadow</code></td><td><code>tooltip</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-shadow</code></td><td>funnel-chart 的 tooltip 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-funnel-chart-tooltip-swatch-radius</code></td><td><code>tooltip-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>funnel-chart 的 tooltip-swatch 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：状态 · 出现（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-fade-in</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立；<code>opacity</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>绘图区不随文字方向镜像：<code>align=&quot;start&quot;</code> 始终靠左缘，转化率在左、外侧标签在右。</li><li>提示框的内容随文字方向排列。</li></ul>',56))])}const P=l(s,[["render",u]]);export{q as __pageData,P as default};
